for (const native of [true, false]) for (const repair of [true, false]) test(`${native ? 'Native' : 'public'} historical queue and unchanged return preserve the complete accepted state (repair=${repair})`, async t => {
  const f = await fixture(t, native);
  f.status.status = 'Failed';
  f.status.checkpointMessage = '保留完整历史状态🌿'.repeat(7000);
  const source = f.capture();
  const accepted = await f.adopt(source);
  const {runId} = accepted.state;
  if (repair) f.store.db.run('DELETE FROM run_consumer_sources WHERE run_id=?', [runId]);
  const before = f.counts();
  const result = await f.adopt(source);
  assert.deepEqual(result, {unchanged: !repair, state: accepted.state});
  assert.deepEqual(f.store.rows('SELECT source_revision FROM run_consumer_sources WHERE run_id=?', [runId]).map(row => row.source_revision), [1]);
  assert.deepEqual(f.counts(), before);
  f.retired();
});

for (const native of [true, false]) for (const earlierRequestFails of [true, false]) {
  test(`${native ? 'Native' : 'public'} historical turn checks damaged old request at its original position (request fails=${earlierRequestFails})`, async t => {
    const f = await turnRestoreFixture(t, native);
    const turnId = f.initial.state.turnId;
    const {request_content_id: contentId} = f.store.rows('SELECT request_content_id FROM turns WHERE id=?', [turnId])[0];
    if (f.store.rows('SELECT 1 FROM content_chunks WHERE content_id=? LIMIT 1', [contentId]).length) {
      f.store.db.run('UPDATE content_chunks SET data=zeroblob(length(data)) WHERE content_id=? AND ordinal=0', [contentId]);
    } else {
      f.store.db.run('UPDATE contents SET data=zeroblob(stored_byte_length) WHERE id=?', [contentId]);
    }
    if (earlierRequestFails) f.store.db.run("CREATE TEMP TRIGGER reject_turn_request BEFORE INSERT ON requests WHEN NEW.idempotency_key LIKE 'historical-turn-times:%' BEGIN SELECT RAISE(ABORT,'original_turn_pending_sql'); END");
    f.store.db.run("CREATE TEMP TRIGGER reject_turn_update BEFORE UPDATE OF started_at ON turns BEGIN SELECT RAISE(ABORT,'late_turn_update_sql'); END");
    const before = f.counts();
    await assert.rejects(async () => f.adopt(f.source), earlierRequestFails ? /original_turn_pending_sql/ : /content_integrity_error/);
    assert.deepEqual(f.counts(), before);
    f.retired();
  });
}

test('public historical fixed turn receipt keeps a preparation failure at the original replay position', async t => {
  const f = await turnRestoreFixture(t);
  const turnId = f.initial.state.turnId;
  await f.adopt(f.source);
  f.store.db.run('UPDATE turns SET started_at=NULL,finished_at=NULL WHERE id=?', [turnId]);
  f.store.db.run('UPDATE objects SET revision=? WHERE id=?', [f.turn.revision, turnId]);
  const compute = f.store.dataWriteCompute;
  let attempted = false;
  f.store.setDataWriteCompute({ ...compute, prepare: async request => {
    const prepared = await compute.prepare(request);
    if (request.input.kind === 'turn' && prepared.replayResult) {
      attempted = true;
      throw new Error('actual_turn_replay_transport_failed');
    }
    return prepared;
  } });
  const before = f.counts();
  await assert.rejects(f.adopt(f.source), /actual_turn_replay_transport_failed/);
  assert.ok(attempted);
  assert.deepEqual(f.counts(), before);
  f.retired();
});

test('public older output observation yields between pages of real formal log chunks', async t => {
  const f = await olderOutputFixture(t);
  const runId = f.initial.state.runId;
  const bytesPerChunk = Math.ceil(f.old.length / 145);
  const chunks = [];
  for (let offset = 0; offset < f.old.length; offset += bytesPerChunk) {
    const id = f.store.putContent(f.old.subarray(offset, offset + bytesPerChunk), 'application/octet-stream');
    chunks.push([runId, 'output', chunks.length, id, 1, offset]);
  }
  assert.ok(chunks.length > 128);
  f.store.db.run("DELETE FROM log_chunks WHERE run_id=? AND stream='output'", [runId]);
  for (const values of chunks) f.store.db.run('INSERT INTO log_chunks VALUES(?,?,?,?,?,?)', values);
  let pages = 0;
  let otherTurnRan = false;
  const rows = f.store.rows;
  f.store.rows = function (sql, ...args) {
    const result = rows.call(this, sql, ...args);
    if (/SELECT (?:sequence,)?content_id FROM log_chunks WHERE run_id=\? AND stream='output'/i.test(sql)) {
      assert.ok(result.length <= 128, 'Source materialized the complete formal log');
      if (++pages === 1) setImmediate(() => { otherTurnRan = true; });
      else assert.ok(otherTurnRan, 'the next page must yield to other work');
    }
    return result;
  };
  try {
    const result = await f.adopt(f.source, f.input);
    assert.deepEqual(result, {unchanged: true, state: f.initial.state});
    assert.ok(pages >= 2);
  } finally {
    f.store.rows = rows;
  }
  f.retired();
});
